Got it. You want a **C++ program** that performs **addition and subtraction of distances (in feet and inches)** using **constructor overloading** and a **friend function**. The screenshot shows the expected input/output flow.

Here’s the complete C++ code:  

```cpp
#include <iostream>
using namespace std;

class Distance {
    int feet, inches;

public:
    // Default constructor
    Distance() {
        feet = 0;
        inches = 0;
    }

    // Parameterized constructor
    Distance(int f, int i) {
        feet = f;
        inches = i;
        normalize();
    }

    // Normalize function to adjust inches >= 12
    void normalize() {
        if (inches >= 12) {
            feet += inches / 12;
            inches = inches % 12;
        }
        else if (inches < 0) {
            int borrow = (abs(inches) + 11) / 12;
            feet -= borrow;
            inches += borrow * 12;
        }
    }

    // Friend functions for addition and subtraction
    friend Distance add(Distance d1, Distance d2);
    friend Distance subtract(Distance d1, Distance d2);

    // Display function
    void display() {
        cout << "Feet: " << feet << " Inches: " << inches << endl;
    }
};

// Friend function to add distances
Distance add(Distance d1, Distance d2) {
    Distance temp;
    temp.feet = d1.feet + d2.feet;
    temp.inches = d1.inches + d2.inches;
    temp.normalize();
    return temp;
}

// Friend function to subtract distances
Distance subtract(Distance d1, Distance d2) {
    Distance temp;
    temp.feet = d1.feet - d2.feet;
    temp.inches = d1.inches - d2.inches;
    temp.normalize();
    return temp;
}

int main() {
    int f1, i1, f2, i2, choice;

    cout << "Enter feet and inches for first length\n";
    cin >> f1 >> i1;
    Distance d1(f1, i1);

    cout << "Enter feet and inches for second length\n";
    cin >> f2 >> i2;
    Distance d2(f2, i2);

    do {
        cout << "enter 1 for sum\n";
        cout << "enter 2 for difference\n";
        cout << "enter 3 to exit\n";
        cin >> choice;

        switch (choice) {
        case 1: {
            Distance sum = add(d1, d2);
            cout << "Sum of distances:\n";
            sum.display();
            break;
        }
        case 2: {
            Distance diff = subtract(d1, d2);
            cout << "Difference of distances:\n";
            diff.display();
            break;
        }
        case 3:
            cout << "exit\n";
            break;
        default:
            cout << "Invalid choice!\n";
        }
    } while (choice != 3);

    return 0;
}
```

